function log(text){S.activity.unshift({id:uid(),date:today(),text,user:user().name});S.activity=S.activity.slice(0,40)}
function toast(text){const t=$('#toast');t.textContent='✓  '+text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function tag(text){return `<span class="tag ${slug(text)}">${esc(text)}</span>`}
function quoteTotals(q){const subtotal=q.items.reduce((s,i)=>s+(+i.qty||0)*(+i.price||0),0),discount=q.items.reduce((s,i)=>s+(+i.qty||0)*(+i.price||0)*(+i.discount||0)/100,0),net=subtotal-discount,tax=net*(+q.tax||0)/100;return{subtotal,discount,net,tax,total:net+tax}}
function nextFolio(prefix,list){const n=Math.max(0,...list.map(x=>+(x.folio||'').replace(/\D/g,'')))+1;return `${prefix}-${String(n).padStart(4,'0')}`}
function openModal(title,subtitle,body,actions='',wide=false){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle||''}</p></div><button class="modal-close" data-close>×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`;$$('[data-close]',$('#modalRoot')).forEach(b=>b.onclick=closeModal);$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function closeModal(){$('#modalRoot').innerHTML=''}
function sectionHead(title,subtitle,actions=''){return `<div class="section-head"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function stat(icon,label,value,note,color=''){return `<article class="stat"><span class="stat-icon ${color}">${icon}</span><div><small>${label}</small><h3>${value}</h3><p>${note}</p></div></article>`}
function empty(icon,title,text){return `<div class="empty"><span>${icon}</span><strong>${title}</strong><p>${text}</p></div>`}
function setPage(title,eyebrow){$('#pageTitle').textContent=title;$('#pageEyebrow').textContent=eyebrow}
function roleAllowed(view){const rules={Administrador:['dashboard','quotes','tracking','clients','suppliers','catalog','inventory','production','reports','admin'],Producción:['dashboard','suppliers','catalog','inventory','production','reports'],Almacén:['dashboard','suppliers','catalog','inventory','reports']};return (rules[user().role]||rules.Almacén).includes(view)}
function go(view){if(!roleAllowed(view)){toast('Tu rol no tiene acceso a este módulo');return}currentView=view;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function render(){const views={dashboard:renderDashboard,quotes:renderQuotes,tracking:renderTracking,clients:renderClients,suppliers:renderSuppliers,catalog:renderCatalog,inventory:renderInventory,production:renderProduction,reports:renderReports,admin:renderAdmin};(views[currentView]||renderDashboard)();updateShell()}
function updateShell(){enforceDemoAdmin();const u=user();$('#userName').textContent=u.name;$('#userRole').textContent=u.role;$('#userInitials').textContent=u.name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#quoteBadge').textContent=S.quotations.filter(q=>['Borrador','Enviada','Pendiente'].includes(q.status)).length;$$('.nav-item').forEach(x=>x.classList.toggle('hidden',!roleAllowed(x.dataset.view)))}

function renderDashboard(){setPage('Resumen','OPERACIÓN GENERAL');const approved=S.quotations.filter(q=>q.status==='Aprobada'),sales=approved.reduce((s,q)=>s+quoteTotals(q).total,0),low=S.materials.filter(m=>m.stock<m.min),value=S.materials.reduce((s,m)=>s+m.stock*m.price,0),cons={};S.movements.filter(m=>m.type==='OUT').forEach(m=>cons[m.materialId]=(cons[m.materialId]||0)+m.qty);const months=[['Mar',61000],['Abr',88000],['May',102000],['Jun',121000],['Jul',146000],['Ago',sales||184320]],max=Math.max(...months.map(x=>x[1]));$('#content').innerHTML=`<div class="hero"><div><span class="pill">● Operación sincronizada</span><h2>Tu producción, bajo control.</h2><p>Cotizaciones, clientes, materiales y fabricación en un solo lugar.</p></div></div><div class="metrics">${stat('$','VENTAS APROBADAS',money(sales),'Cotizaciones aprobadas','blue')}${stat('▤','COTIZACIONES ABIERTAS',S.quotations.filter(q=>!['Aprobada','Rechazada','Cancelada'].includes(q.status)).length,'Requieren seguimiento','orange')}${stat('▥','VALOR DE INVENTARIO',money(value),'Existencias × costo','teal')}${stat('!','MATERIAL POR REPONER',low.length,'Por debajo del mínimo','red')}</div><div class="grid two"><article class="panel"><div class="panel-head"><div><h3>Monto cotizado por mes</h3><p>Evolución comercial de los últimos seis meses</p></div></div><div class="chart-wrap"><div class="chart">${months.map((m,i)=>`<div class="chart-col"><i class="chart-bar ${i===months.length-1?'accent':''}" style="height:${Math.max(5,m[1]/max*100)}%"></i><small>${m[0]}</small></div>`).join('')}</div></div></article><article class="panel"><div class="panel-head"><div><h3>Consumo de materiales</h3><p>Salidas acumuladas registradas</p></div><button class="btn btn-outline btn-sm" data-go="inventory">Ver inventario</button></div>${Object.entries(cons).slice(0,5).map(([id,v])=>{const m=material(id);const pct=Math.min(100,v/Math.max(...Object.values(cons))*100);return `<div class="progress-row"><div class="progress-label"><span>${esc(m.name)}</span><b>${num(v)} ${m.unit}</b></div><div class="progress"><i class="orange" style="width:${pct}%"></i></div></div>`}).join('')||'<p class="hint">Sin consumos registrados.</p>'}</article><article class="panel"><div class="panel-head"><div><h3>Cotizaciones recientes</h3><p>Últimos movimientos comerciales</p></div><button class="btn btn-outline btn-sm" data-go="quotes">Ver todas</button></div>${quoteTable(S.quotations.slice().sort((a,b)=>b.issue.localeCompare(a.issue)).slice(0,4),false)}</article><article class="panel"><div class="panel-head"><div><h3>Alertas de materiales</h3><p>Existencias por debajo del mínimo</p></div></div>${low.map(m=>`<div class="progress-row"><div class="progress-label"><span><b>${esc(m.name)}</b> · mín. ${num(m.min)} ${m.unit}</span><b class="danger-text">${num(m.stock)} ${m.unit}</b></div><div class="progress"><i class="red" style="width:${Math.min(100,m.stock/m.min*100)}%"></i></div></div>`).join('')||'<p class="hint">Todo el inventario está en nivel correcto.</p>'}</article></div>`;bindGo()}
function quoteTable(list,actions=true){return `<div class="table-wrap"><table><thead><tr><th>FOLIO</th><th>FECHA</th><th>CLIENTE</th><th>SIN IVA</th><th>CON IVA</th><th>ESTADO</th>${actions?'<th>ACCIONES</th>':''}</tr></thead><tbody>${list.map(q=>{const t=quoteTotals(q);return `<tr><td><strong class="link" data-view-quote="${q.id}">${q.folio}</strong></td><td>${dateFmt(q.issue)}</td><td>${esc(client(q.clientId).name)}</td><td>${money(t.net)}</td><td><b>${money(t.total)}</b></td><td>${tag(q.status)}</td>${actions?`<td><div class="actions"><button class="btn btn-outline btn-sm" data-view-quote="${q.id}">Ver</button><button class="btn btn-outline btn-sm" data-edit-quote="${q.id}">Editar</button><button class="btn btn-outline btn-sm" data-duplicate-quote="${q.id}">Duplicar</button><button class="btn btn-outline btn-sm" data-status-quote="${q.id}">Estado</button></div></td>`:''}</tr>`}).join('')||`<tr><td colspan="7">Sin cotizaciones</td></tr>`}</tbody></table></div>`}
function bindQuoteActions(){$$('[data-view-quote]').forEach(b=>b.onclick=()=>viewQuote(b.dataset.viewQuote));$$('[data-edit-quote]').forEach(b=>b.onclick=()=>openQuoteForm(b.dataset.editQuote));$$('[data-duplicate-quote]').forEach(b=>b.onclick=()=>duplicateQuote(b.dataset.duplicateQuote));$$('[data-status-quote]').forEach(b=>b.onclick=()=>statusQuote(b.dataset.statusQuote))}
function renderQuotes(){setPage('Cotizaciones','ÁREA COMERCIAL');$('#content').innerHTML=sectionHead('Cotizaciones','Crea, consulta, edita y da seguimiento a propuestas comerciales.','<button class="primary" id="newQuote">＋ Nueva cotización</button>')+`<div class="toolbar"><input class="search" id="quoteSearch" placeholder="Buscar folio o cliente…"><select id="quoteStatus"><option value="">Todos los estados</option>${['Borrador','Enviada','Pendiente','Aprobada','Rechazada','Cancelada'].map(x=>`<option>${x}</option>`).join('')}</select></div><article class="panel" id="quoteList"></article>`;const refresh=()=>{const s=$('#quoteSearch').value.toLowerCase(),st=$('#quoteStatus').value,list=S.quotations.filter(q=>(q.folio+client(q.clientId).name).toLowerCase().includes(s)&&(!st||q.status===st)).sort((a,b)=>b.issue.localeCompare(a.issue));$('#quoteList').innerHTML=quoteTable(list);bindQuoteActions()};$('#newQuote').onclick=()=>openQuoteForm();$('#quoteSearch').oninput=refresh;$('#quoteStatus').onchange=refresh;refresh()}

function openQuoteForm(id){const original=id?S.quotations.find(q=>q.id===id):null,draft=original?structuredClone(original):{id:uid(),folio:nextFolio('COT',S.quotations),clientId:S.clients[0]?.id||'',issue:today(),due:addDays(today(),S.company.validity||15),status:'Borrador',user:user().name,tax:S.company.tax||16,notes:'',items:[{id:uid(),productId:S.products[0].id,description:S.products[0].name,qty:1000,unit:S.products[0].unit,price:S.products[0].price,discount:0}],history:[]};openModal(original?`Editar ${draft.folio}`:'Nueva cotización','Captura cliente, vigencia y una o varias partidas.',`<div class="form-grid"><div class="field full"><label>CLIENTE</label><select id="qClient">${S.clients.filter(c=>c.status==='Activo').map(c=>`<option value="${c.id}" ${c.id===draft.clientId?'selected':''}>${esc(c.name)}${c.company?' · '+esc(c.company):''}</option>`).join('')}</select></div><div class="field"><label>FECHA DE EMISIÓN</label><input type="date" id="qIssue" value="${draft.issue}"></div><div class="field"><label>VIGENCIA HASTA</label><input type="date" id="qDue" value="${draft.due}"></div></div><div class="quote-lines"><div class="panel-head"><div><h3>Productos / partidas</h3><p>Agrega todos los productos requeridos.</p></div><button class="btn btn-outline btn-sm" id="addLine">＋ Agregar partida</button></div><div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>DESCRIPCIÓN</th><th>CANT.</th><th>PRECIO</th><th>DESC. %</th><th>IMPORTE</th><th></th></tr></thead><tbody id="lineRows"></tbody></table></div></div><div class="grid two" style="margin-top:15px"><div class="panel"><h3 style="font-size:13px">Explosión de materiales</h3><p class="hint">Calculada con las fórmulas del catálogo.</p><div class="explosion" id="explosion"></div><p class="hint" id="productionCost"></p></div><div><div class="field"><label>NOTAS Y CONDICIONES</label><textarea rows="4" id="qNotes">${esc(draft.notes)}</textarea></div><div class="field" style="margin-top:10px"><label>IVA (%)</label><input type="number" id="qTax" value="${draft.tax}" min="0" max="30"></div><div class="totals" id="quoteTotals"></div></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveQuote">Guardar cotización</button>`,true);
 function sync(){draft.clientId=$('#qClient').value;draft.issue=$('#qIssue').value;draft.due=$('#qDue').value;draft.notes=$('#qNotes').value;draft.tax=+$('#qTax').value||0}
 function totals(){sync();const t=quoteTotals(draft);$('#quoteTotals').innerHTML=`<div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Descuentos</span><b>− ${money(t.discount)}</b></div><div class="total-without-tax"><span>Total sin IVA</span><b>${money(t.net)}</b></div><div><span>IVA ${draft.tax}%</span><b>${money(t.tax)}</b></div><div class="grand"><span>Total con IVA</span><span>${money(t.total)}</span></div>`;const req={},cost={};draft.items.forEach(it=>{const p=product(it.productId);Object.entries(p.recipe||{}).forEach(([mid,per])=>{req[mid]=(req[mid]||0)+per*(+it.qty||0);cost[mid]=(cost[mid]||0)+per*(+it.qty||0)*material(mid).price})});$('#explosion').innerHTML=Object.entries(req).map(([mid,q])=>`<div><small>${esc(material(mid).name)}</small><strong>${num(q)} ${material(mid).unit}</strong></div>`).join('')||'<span class="hint">Sin fórmula asociada.</span>';const c=Object.values(cost).reduce((a,b)=>a+b,0);$('#productionCost').innerHTML=`Costo estimado de materiales: <b>${money(c)}</b> · Margen estimado: <b>${money(t.total-c)}</b>`}
 function rows(){$('#lineRows').innerHTML=draft.items.map((it,i)=>`<tr data-line="${i}"><td><select class="line-product">${S.products.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.id===it.productId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></td><td><input class="desc" value="${esc(it.description)}"></td><td><input class="qty" type="number" min="1" value="${it.qty}"></td><td><input class="price" type="number" min="0" step=".01" value="${it.price}"></td><td><input class="discount" type="number" min="0" max="100" value="${it.discount||0}"></td><td><b>${money(it.qty*it.price*(1-(it.discount||0)/100))}</b></td><td><button class="btn btn-danger btn-sm remove-line">×</button></td></tr>`).join('');$$('[data-line]').forEach(row=>{const i=+row.dataset.line,it=draft.items[i];$('.line-product',row).onchange=e=>{const p=product(e.target.value);Object.assign(it,{productId:p.id,description:p.name,unit:p.unit,price:p.price});rows();totals()};$('.desc',row).oninput=e=>it.description=e.target.value;$('.qty',row).oninput=e=>{it.qty=+e.target.value||0;rows();totals()};$('.price',row).oninput=e=>{it.price=+e.target.value||0;rows();totals()};$('.discount',row).oninput=e=>{it.discount=+e.target.value||0;rows();totals()};$('.remove-line',row).onclick=()=>{if(draft.items.length===1)return toast('La cotización necesita al menos una partida');draft.items.splice(i,1);rows();totals()}})}
 rows();totals();['qClient','qIssue','qDue','qTax','qNotes'].forEach(x=>$('#'+x).oninput=totals);$('#addLine').onclick=()=>{const p=S.products.find(x=>x.active)||S.products[0];draft.items.push({id:uid(),productId:p.id,description:p.name,qty:1,unit:p.unit,price:p.price,discount:0});rows();totals()};$('#saveQuote').onclick=()=>{sync();if(!draft.clientId||!draft.items.length)return toast('Completa el cliente y las partidas');if(original)Object.assign(original,draft);else{draft.history=[{status:'Borrador',date:today(),user:user().name,note:'Creada'}];S.quotations.unshift(draft)}log(`${draft.folio} ${original?'actualizada':'creada'}`);save();closeModal();toast('Cotización guardada');go('quotes')};
}
function viewQuote(id){const q=S.quotations.find(x=>x.id===id);if(!q)return;const c=client(q.clientId),t=quoteTotals(q);openModal(`Cotización ${q.folio}`,`${q.status} · ${dateFmt(q.issue)}`,`<div class="doc"><div class="doc-top"><div class="doc-company"><img src="assets/logo-gromex.png" alt="GROMEX"><p class="hint">${esc(S.company.legal)}<br>${esc(S.company.rfc)} · ${esc(S.company.phone)}<br>${esc(S.company.email)}</p></div><div><div style="text-align:right">${tag(q.status)}</div><p class="hint">Emisión: ${dateFmt(q.issue)}<br>Vigencia: ${dateFmt(q.due)}</p></div></div><div class="grid two"><div><small class="hint">CLIENTE</small><h3>${esc(c.name)}</h3><p class="hint">${esc(c.company)}<br>${esc(c.address)}<br>${esc(c.phone)} · ${esc(c.email)}</p></div><div class="doc-dual-total"><div><small class="hint">TOTAL SIN IVA</small><strong>${money(t.net)}</strong></div><div><small class="hint">TOTAL CON IVA</small><div class="doc-total">${money(t.total)}</div></div></div></div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>DESCRIPCIÓN</th><th>CANTIDAD</th><th>PRECIO</th><th>DESC.</th><th>IMPORTE</th></tr></thead><tbody>${q.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${num(i.qty)} ${esc(i.unit)}</td><td>${money(i.price)}</td><td>${num(i.discount)}%</td><td><b>${money(i.qty*i.price*(1-i.discount/100))}</b></td></tr>`).join('')}</tbody></table></div><div class="totals"><div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Descuento</span><b>− ${money(t.discount)}</b></div><div class="total-without-tax"><span>Total sin IVA</span><b>${money(t.net)}</b></div><div><span>IVA ${q.tax}%</span><b>${money(t.tax)}</b></div><div class="grand"><span>Total con IVA</span><span>${money(t.total)}</span></div></div><p class="hint" style="margin-top:18px">${esc(q.notes)||'Cotización sujeta a disponibilidad de materiales y programa de producción.'}</p></div>`,`<button class="secondary" data-close>Cerrar</button><button class="secondary" id="editFromView">Editar</button><button class="secondary" id="statusFromView">Cambiar estado</button><button class="btn btn-blue" id="printQuote">Imprimir / PDF</button>`,true);$('#printQuote').onclick=()=>window.print();$('#editFromView').onclick=()=>{closeModal();openQuoteForm(id)};$('#statusFromView').onclick=()=>{closeModal();statusQuote(id)}}
function duplicateQuote(id){const q=S.quotations.find(x=>x.id===id),copy=structuredClone(q);copy.id=uid();copy.folio=nextFolio('COT',S.quotations);copy.issue=today();copy.due=addDays(today(),S.company.validity||15);copy.status='Borrador';copy.user=user().name;copy.items.forEach(i=>i.id=uid());copy.history=[{status:'Borrador',date:today(),user:user().name,note:`Duplicada de ${q.folio}`}];S.quotations.unshift(copy);log(`${copy.folio} duplicada`);save();toast(`Cotización duplicada: ${copy.folio}`);render()}
function statusQuote(id){const q=S.quotations.find(x=>x.id===id);openModal(`Cambiar estado · ${q.folio}`,'Registra el avance comercial de la cotización.',`<div class="form-grid"><div class="field full"><label>NUEVO ESTADO</label><select id="newStatus">${['Borrador','Enviada','Pendiente','Aprobada','Rechazada','Cancelada'].map(s=>`<option ${s===q.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label>NOTA DE SEGUIMIENTO</label><textarea id="statusNote" rows="3" placeholder="Comentario opcional"></textarea></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveStatus">Guardar estado</button>`);$('#saveStatus').onclick=()=>{q.status=$('#newStatus').value;q.history=q.history||[];q.history.push({status:q.status,date:today(),user:user().name,note:$('#statusNote').value});log(`${q.folio} → ${q.status}`);save();closeModal();toast('Estado actualizado');render()}}
function renderTracking(){setPage('Seguimiento','EMBUDO COMERCIAL');const states=['Borrador','Enviada','Pendiente','Aprobada','Rechazada'];$('#content').innerHTML=sectionHead('Seguimiento de cotizaciones','Visualiza el avance comercial por estado.','<button class="primary" id="trackNew">＋ Nueva cotización</button>')+`<div class="kanban">${states.map(st=>{const list=S.quotations.filter(q=>q.status===st);return `<section class="kanban-col"><div class="kanban-head"><span>${st}</span><span>${list.length}</span></div>${list.map(q=>`<article class="kanban-card" data-view-quote="${q.id}"><strong>${q.folio}</strong><small>${esc(client(q.clientId).name)}</small><strong style="margin-top:10px">${money(quoteTotals(q).total)}</strong><small>${dateFmt(q.issue)} · ${esc(q.user)}</small></article>`).join('')}</section>`}).join('')}</div>`;$('#trackNew').onclick=()=>openQuoteForm();bindQuoteActions()}

function renderClients(){setPage('Clientes','DIRECTORIO COMERCIAL');$('#content').innerHTML=sectionHead('Clientes','Directorio, datos de contacto e historial comercial.','<button class="primary" id="newClient">＋ Nuevo cliente</button>')+`<div class="toolbar"><input class="search" id="clientSearch" placeholder="Buscar nombre, empresa o teléfono…"><select id="clientStatus"><option value="">Todos</option><option>Activo</option><option>Inactivo</option></select></div><div class="card-list" id="clientCards"></div>`;const refresh=()=>{const s=$('#clientSearch').value.toLowerCase(),st=$('#clientStatus').value,list=S.clients.filter(c=>(c.name+c.company+c.phone).toLowerCase().includes(s)&&(!st||c.status===st));$('#clientCards').innerHTML=list.map(c=>{const qs=S.quotations.filter(q=>q.clientId===c.id),total=qs.filter(q=>q.status==='Aprobada').reduce((a,q)=>a+quoteTotals(q).total,0);return `<article class="entity-card"><header><div><h3>${esc(c.name)}</h3><div class="meta">${esc(c.company)||'Cliente particular'}</div></div>${tag(c.status)}</header><div class="big">${money(total)}</div><div class="meta">Ventas aprobadas · ${qs.length} cotizaciones</div><div class="meta" style="margin-top:12px">${esc(c.phone)}<br>${esc(c.email)}</div><footer><button class="btn btn-outline btn-sm" data-client-detail="${c.id}">Ver historial</button><button class="btn btn-outline btn-sm" data-client-edit="${c.id}">Editar</button></footer></article>`}).join('')||empty('♙','Sin clientes','No hay resultados con estos filtros.');$$('[data-client-edit]').forEach(b=>b.onclick=()=>clientModal(b.dataset.clientEdit));$$('[data-client-detail]').forEach(b=>b.onclick=()=>clientDetail(b.dataset.clientDetail))};$('#newClient').onclick=()=>clientModal();$('#clientSearch').oninput=refresh;$('#clientStatus').onchange=refresh;refresh()}
function clientModal(id){const old=id?S.clients.find(c=>c.id===id):null,c=old?structuredClone(old):{id:uid(),name:'',company:'',phone:'',email:'',address:'',status:'Activo'};openModal(old?'Editar cliente':'Nuevo cliente','Información comercial y de contacto.',`<div class="form-grid"><div class="field"><label>NOMBRE / CONTACTO</label><input id="cName" value="${esc(c.name)}"></div><div class="field"><label>EMPRESA / RAZÓN SOCIAL</label><input id="cCompany" value="${esc(c.company)}"></div><div class="field"><label>TELÉFONO</label><input id="cPhone" value="${esc(c.phone)}"></div><div class="field"><label>CORREO</label><input type="email" id="cEmail" value="${esc(c.email)}"></div><div class="field full"><label>DIRECCIÓN</label><input id="cAddress" value="${esc(c.address)}"></div><div class="field"><label>ESTADO</label><select id="cStatus"><option ${c.status==='Activo'?'selected':''}>Activo</option><option ${c.status==='Inactivo'?'selected':''}>Inactivo</option></select></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveClient">Guardar cliente</button>`);$('#saveClient').onclick=()=>{c.name=$('#cName').value.trim();if(!c.name)return toast('Escribe el nombre del cliente');c.company=$('#cCompany').value;c.phone=$('#cPhone').value;c.email=$('#cEmail').value;c.address=$('#cAddress').value;c.status=$('#cStatus').value;if(old)Object.assign(old,c);else S.clients.push(c);log(`Cliente ${c.name} guardado`);save();closeModal();toast('Cliente guardado');render()}}
function clientDetail(id){const c=client(id),qs=S.quotations.filter(q=>q.clientId===id),approved=qs.filter(q=>q.status==='Aprobada').reduce((s,q)=>s+quoteTotals(q).total,0);openModal(c.name,c.company||'Cliente particular',`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${stat('▤','COTIZACIONES',qs.length,'Histórico','blue')}${stat('✓','APROBADAS',qs.filter(q=>q.status==='Aprobada').length,'Conversiones','teal')}${stat('$','VENTAS',money(approved),'Monto aprobado','orange')}</div><p class="hint">${esc(c.address)} · ${esc(c.phone)} · ${esc(c.email)}</p><div style="margin-top:16px">${quoteTable(qs)}</div>`,`<button class="secondary" data-close>Cerrar</button>`,true);bindQuoteActions()}

function renderSuppliers(){setPage('Proveedores','COMPRAS Y ABASTECIMIENTO');$('#content').innerHTML=sectionHead('Proveedores','Directorio de abastecimiento y materiales suministrados.','<button class="primary" id="newSupplier">＋ Nuevo proveedor</button>')+`<div class="metrics">${stat('♜','PROVEEDORES',S.suppliers.length,'Registrados','blue')}${stat('✓','ACTIVOS',S.suppliers.filter(s=>s.status==='Activo').length,'Disponibles para compra','teal')}${stat('▥','MATERIALES ASIGNADOS',S.materials.filter(m=>S.suppliers.some(s=>s.name===m.supplier)).length,'Con proveedor identificado','orange')}${stat('$','VALOR ABASTECIDO',money(S.materials.reduce((a,m)=>a+m.stock*m.price,0)),'Inventario actual','blue')}</div><div class="toolbar"><input class="search" id="supplierSearch" placeholder="Buscar proveedor, contacto o categoría…"><select id="supplierStatus"><option value="">Todos</option><option>Activo</option><option>Inactivo</option></select></div><div class="card-list" id="supplierCards"></div>`;const refresh=()=>{const q=$('#supplierSearch').value.toLowerCase(),st=$('#supplierStatus').value,list=S.suppliers.filter(s=>(s.name+s.contact+s.category).toLowerCase().includes(q)&&(!st||s.status===st));$('#supplierCards').innerHTML=list.map(s=>{const mats=S.materials.filter(m=>m.supplier===s.name),value=mats.reduce((a,m)=>a+m.stock*m.price,0);return `<article class="entity-card"><header><div><h3>${esc(s.name)}</h3><div class="meta">${esc(s.category)||'Proveedor general'}</div></div>${tag(s.status)}</header><div class="big">${mats.length} <span class="hint">materiales</span></div><div class="meta">Valor actual: ${money(value)}</div><div class="meta" style="margin-top:12px"><b>${esc(s.contact)}</b><br>${esc(s.phone)}<br>${esc(s.email)}</div><footer><button class="btn btn-outline btn-sm" data-supplier-detail="${s.id}">Ver materiales</button><button class="btn btn-outline btn-sm" data-supplier-edit="${s.id}">Editar</button></footer></article>`}).join('')||empty('♜','Sin proveedores','No hay resultados con estos filtros.');$$('[data-supplier-detail]').forEach(b=>b.onclick=()=>supplierDetail(b.dataset.supplierDetail));$$('[data-supplier-edit]').forEach(b=>b.onclick=()=>supplierModal(b.dataset.supplierEdit))};$('#newSupplier').onclick=()=>supplierModal();$('#supplierSearch').oninput=refresh;$('#supplierStatus').onchange=refresh;refresh()}
function supplierModal(id){const old=id?S.suppliers.find(s=>s.id===id):null,s=old?structuredClone(old):{id:uid(),name:'',rfc:'',contact:'',phone:'',email:'',address:'',category:'',terms:'Contado',status:'Activo'},oldName=old?.name;openModal(old?'Editar proveedor':'Nuevo proveedor','Datos fiscales, contacto y condiciones comerciales.',`<div class="form-grid"><div class="field full"><label>NOMBRE / RAZÓN SOCIAL</label><input id="sName" value="${esc(s.name)}"></div><div class="field"><label>RFC</label><input id="sRfc" value="${esc(s.rfc)}"></div><div class="field"><label>CATEGORÍA</label><input id="sCategory" value="${esc(s.category)}" placeholder="Cemento, agregados, químicos…"></div><div class="field"><label>CONTACTO</label><input id="sContact" value="${esc(s.contact)}"></div><div class="field"><label>TELÉFONO</label><input id="sPhone" value="${esc(s.phone)}"></div><div class="field"><label>CORREO</label><input type="email" id="sEmail" value="${esc(s.email)}"></div><div class="field"><label>CONDICIONES DE PAGO</label><input id="sTerms" value="${esc(s.terms)}"></div><div class="field full"><label>DIRECCIÓN</label><input id="sAddress" value="${esc(s.address)}"></div><div class="field"><label>ESTADO</label><select id="sStatus"><option ${s.status==='Activo'?'selected':''}>Activo</option><option ${s.status==='Inactivo'?'selected':''}>Inactivo</option></select></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveSupplier">Guardar proveedor</button>`);$('#saveSupplier').onclick=()=>{s.name=$('#sName').value.trim();if(!s.name)return toast('Escribe el nombre del proveedor');s.rfc=$('#sRfc').value;s.category=$('#sCategory').value;s.contact=$('#sContact').value;s.phone=$('#sPhone').value;s.email=$('#sEmail').value;s.terms=$('#sTerms').value;s.address=$('#sAddress').value;s.status=$('#sStatus').value;if(old){Object.assign(old,s);if(oldName!==s.name)S.materials.filter(m=>m.supplier===oldName).forEach(m=>m.supplier=s.name)}else S.suppliers.push(s);log(`Proveedor ${s.name} guardado`);save();closeModal();toast('Proveedor guardado');render()}}
function supplierDetail(id){const s=S.suppliers.find(x=>x.id===id),mats=S.materials.filter(m=>m.supplier===s.name),value=mats.reduce((a,m)=>a+m.stock*m.price,0);openModal(s.name,`${s.category} · ${s.terms}`,`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${stat('▥','MATERIALES',mats.length,'Suministrados','blue')}${stat('$','VALOR ACTUAL',money(value),'Inventario asociado','teal')}${stat('✓','ESTADO',s.status,'Relación comercial','orange')}</div><p class="hint"><b>${esc(s.contact)}</b> · ${esc(s.phone)} · ${esc(s.email)}<br>${esc(s.address)} · RFC ${esc(s.rfc)||'No registrado'}</p><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>MATERIAL</th><th>EXISTENCIA</th><th>COSTO UNITARIO</th><th>VALOR</th></tr></thead><tbody>${mats.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${num(m.stock)} ${m.unit}</td><td>${money(m.price)}</td><td>${money(m.stock*m.price)}</td></tr>`).join('')||'<tr><td colspan="4">No hay materiales asociados.</td></tr>'}</tbody></table></div>`,`<button class="secondary" data-close>Cerrar</button><button class="primary" id="editSupplierFromDetail">Editar proveedor</button>`,true);$('#editSupplierFromDetail').onclick=()=>{closeModal();supplierModal(id)}}

function renderCatalog(){setPage('Productos y fórmulas','CATÁLOGO DE PRODUCCIÓN');$('#content').innerHTML=sectionHead('Productos y fórmulas','Administra precios de venta, insumos y recetas de fabricación.',`<button class="primary" id="catalogNew">＋ ${catalogTab==='products'?'Nuevo producto':'Nuevo material'}</button>`)+`<div class="tabs"><button class="${catalogTab==='products'?'active':''}" data-catalog-tab="products">Productos y fórmulas</button><button class="${catalogTab==='materials'?'active':''}" data-catalog-tab="materials">Catálogo de materiales</button></div><div id="catalogBody"></div>`;$$('[data-catalog-tab]').forEach(b=>b.onclick=()=>{catalogTab=b.dataset.catalogTab;renderCatalog()});if(catalogTab==='products'){$('#catalogBody').innerHTML=`<div class="card-list">${S.products.map(p=>{const cost=Object.entries(p.recipe||{}).reduce((s,[mid,q])=>s+q*material(mid).price,0);return `<article class="entity-card"><header><div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.sku)} · ${esc(p.unit)}</div></div>${tag(p.active?'Activo':'Inactivo')}</header><div class="big">${money(p.price)} <span class="hint">/ ${p.unit}</span></div><div class="meta">Costo material estimado: ${money(cost)} · Margen: ${money(p.price-cost)}</div><div class="recipe"><b style="font-size:10px">FÓRMULA POR ${p.unit.toUpperCase()}</b>${Object.entries(p.recipe||{}).filter(x=>+x[1]).map(([mid,q])=>`<div class="recipe-row"><span>${esc(material(mid).name)}</span><b>${num(q)} ${material(mid).unit}</b></div>`).join('')||'<p class="hint">Sin fórmula configurada</p>'}</div><footer><button class="btn btn-outline btn-sm" data-product-edit="${p.id}">Editar producto y fórmula</button></footer></article>`}).join('')}</div>`;$$('[data-product-edit]').forEach(b=>b.onclick=()=>productModal(b.dataset.productEdit));$('#catalogNew').onclick=()=>productModal()}else{$('#catalogBody').innerHTML=`<article class="panel"><div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>UNIDAD</th><th>PROVEEDOR</th><th>COSTO UNITARIO</th><th>EXISTENCIA</th><th>MÍNIMO</th><th></th></tr></thead><tbody>${S.materials.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.unit)}</td><td>${esc(m.supplier)}</td><td>${money(m.price)}</td><td>${num(m.stock)} ${m.unit}</td><td>${num(m.min)} ${m.unit}</td><td><button class="btn btn-outline btn-sm" data-material-edit="${m.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></article>`;$$('[data-material-edit]').forEach(b=>b.onclick=()=>materialModal(b.dataset.materialEdit));$('#catalogNew').onclick=()=>materialModal()}}
function productModal(id){const old=id?S.products.find(p=>p.id===id):null,p=old?structuredClone(old):{id:uid(),name:'',sku:'',unit:'pza',price:0,active:true,recipe:{}};openModal(old?'Editar producto y fórmula':'Nuevo producto','Define el precio y el consumo de materiales por unidad producida.',`<div class="form-grid"><div class="field full"><label>NOMBRE DEL PRODUCTO</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>CLAVE / SKU</label><input id="pSku" value="${esc(p.sku)}"></div><div class="field"><label>UNIDAD</label><input id="pUnit" value="${esc(p.unit)}"></div><div class="field"><label>PRECIO DE VENTA</label><input type="number" min="0" step=".01" id="pPrice" value="${p.price}"></div><div class="field"><label>ESTADO</label><select id="pActive"><option value="1" ${p.active?'selected':''}>Activo</option><option value="0" ${!p.active?'selected':''}>Inactivo</option></select></div></div><div class="panel" style="margin-top:16px"><h3 style="font-size:13px">Fórmula por unidad producida</h3><p class="hint">Indica cuánto material consume una pieza.</p><div class="form-grid" style="margin-top:12px">${S.materials.map(m=>`<div class="field"><label>${esc(m.name)} (${m.unit})</label><input type="number" min="0" step="any" data-recipe="${m.id}" value="${p.recipe[m.id]||0}"></div>`).join('')}</div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveProduct">Guardar producto</button>`,true);$('#saveProduct').onclick=()=>{p.name=$('#pName').value.trim();if(!p.name)return toast('Escribe el nombre del producto');p.sku=$('#pSku').value;p.unit=$('#pUnit').value||'pza';p.price=+$('#pPrice').value||0;p.active=$('#pActive').value==='1';p.recipe={};$$('[data-recipe]').forEach(i=>{if(+i.value)p.recipe[i.dataset.recipe]=+i.value});if(old)Object.assign(old,p);else S.products.push(p);log(`Producto ${p.name} guardado`);save();closeModal();toast('Producto y fórmula guardados');render()}}
function materialModal(id){const old=id?S.materials.find(m=>m.id===id):null,m=old?structuredClone(old):{id:uid(),name:'',unit:'kg',stock:0,min:0,max:100,price:0,icon:'MT',supplier:S.suppliers[0]?.name||''};openModal(old?'Editar material':'Nuevo material','Catálogo, costo y niveles de inventario.',`<div class="form-grid"><div class="field full"><label>NOMBRE</label><input id="mName" value="${esc(m.name)}"></div><div class="field"><label>UNIDAD</label><input id="mUnit" value="${esc(m.unit)}"></div><div class="field"><label>PROVEEDOR</label><select id="mSupplier">${S.suppliers.filter(s=>s.status==='Activo').map(s=>`<option value="${esc(s.name)}" ${s.name===m.supplier?'selected':''}>${esc(s.name)} · ${esc(s.category)}</option>`).join('')}</select></div><div class="field"><label>COSTO UNITARIO</label><input type="number" step=".01" id="mPrice" value="${m.price}"></div><div class="field"><label>EXISTENCIA INICIAL</label><input type="number" step="any" id="mStock" value="${m.stock}"></div><div class="field"><label>STOCK MÍNIMO</label><input type="number" step="any" id="mMin" value="${m.min}"></div><div class="field"><label>CAPACIDAD / MÁXIMO</label><input type="number" step="any" id="mMax" value="${m.max}"></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveMaterial">Guardar material</button>`);$('#saveMaterial').onclick=()=>{m.name=$('#mName').value.trim();if(!m.name)return toast('Escribe el nombre del material');m.unit=$('#mUnit').value;m.supplier=$('#mSupplier').value;m.price=+$('#mPrice').value||0;m.stock=+$('#mStock').value||0;m.min=+$('#mMin').value||0;m.max=+$('#mMax').value||100;m.icon=m.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();if(old)Object.assign(old,m);else S.materials.push(m);log(`Material ${m.name} guardado`);save();closeModal();toast('Material guardado');render()}}

function renderInventory(){setPage('Inventario','ALMACÉN Y MOVIMIENTOS');const low=S.materials.filter(m=>m.stock<m.min);$('#content').innerHTML=sectionHead('Inventario y consumos','Existencias, entradas, salidas y valorización de materia prima.','<button class="secondary" id="newOut">↑ Registrar salida</button><button class="primary" id="newIn">↓ Registrar entrada</button>')+`<div class="metrics">${stat('▥','MATERIALES',S.materials.length,'En catálogo','blue')}${stat('!','BAJO MÍNIMO',low.length,'Requieren compra','red')}${stat('$','VALOR DEL INVENTARIO',money(S.materials.reduce((s,m)=>s+m.stock*m.price,0)),'Existencia × costo','teal')}${stat('⇄','MOVIMIENTOS',S.movements.length,'Histórico total','orange')}</div><div class="inventory-cards">${S.materials.map(m=>{const pct=Math.min(100,m.stock/m.max*100),isLow=m.stock<m.min;return `<article class="material-card"><div class="material-top"><span class="stat-icon ${isLow?'red':'teal'}">${m.icon}</span><div><h3>${esc(m.name)}</h3><p class="hint">${esc(m.supplier)}</p></div>${isLow?tag('Pendiente'):''}</div><div class="amount">${num(m.stock)} <span>${m.unit}</span></div><div class="progress"><i class="${isLow?'red':''}" style="width:${pct}%"></i></div><footer><span>Mín. ${num(m.min)} ${m.unit}</span><span>${Math.round(pct)}% capacidad</span></footer><button class="btn btn-outline btn-sm" style="width:100%;margin-top:14px" data-move-material="${m.id}">Registrar movimiento</button></article>`}).join('')}</div><article class="panel" style="margin-top:17px"><div class="panel-head"><div><h3>Entradas y salidas</h3><p>Filtra por material y rango de fechas.</p></div><button class="btn btn-outline btn-sm" id="exportMoves">Descargar CSV</button></div><div class="toolbar"><select id="moveMaterial"><option value="">Todos los materiales</option>${S.materials.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><input type="date" id="moveFrom"><input type="date" id="moveTo"><button class="btn btn-blue" id="filterMoves">Filtrar</button><button class="secondary" id="clearMoves">Limpiar</button></div><div id="moveResults"></div></article>`;
 const refresh=()=>{const mid=$('#moveMaterial').value,from=$('#moveFrom').value,to=$('#moveTo').value,list=S.movements.filter(x=>(!mid||x.materialId===mid)&&(!from||x.date>=from)&&(!to||x.date<=to)).sort((a,b)=>b.date.localeCompare(a.date)),ins=list.filter(x=>x.type==='IN'),outs=list.filter(x=>x.type==='OUT'),ti=ins.reduce((s,x)=>s+x.qty,0),to2=outs.reduce((s,x)=>s+x.qty,0),u=mid?material(mid).unit:'mov.';$('#moveResults').innerHTML=`<div class="movement-summary">${stat('↓','ENTRADAS',mid?`${num(ti)} ${u}`:`${ins.length} ${u}`,`${ins.length} movimientos`,'teal')}${stat('↑','SALIDAS',mid?`${num(to2)} ${u}`:`${outs.length} ${u}`,`${outs.length} movimientos`,'orange')}${stat('＝','SALDO DEL PERIODO',mid?`${num(ti-to2)} ${u}`:`${list.length} registros`,'Entradas menos salidas','blue')}</div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>MATERIAL</th><th>TIPO</th><th>CANTIDAD</th><th>CONCEPTO</th><th>REFERENCIA</th></tr></thead><tbody>${list.map(x=>{const m=material(x.materialId);return `<tr><td>${dateFmt(x.date)}</td><td><strong>${esc(m.name)}</strong></td><td>${tag(x.type==='IN'?'Entrada':'Salida')}</td><td><b>${x.type==='IN'?'+':'−'}${num(x.qty)} ${m.unit}</b></td><td>${esc(x.concept)}</td><td>${esc(x.reference)}</td></tr>`}).join('')||'<tr><td colspan="6">No hay movimientos en el periodo.</td></tr>'}</tbody></table></div>`;return list};$('#newIn').onclick=()=>movementModal('IN');$('#newOut').onclick=()=>movementModal('OUT');$$('[data-move-material]').forEach(b=>b.onclick=()=>movementModal('IN',b.dataset.moveMaterial));$('#filterMoves').onclick=refresh;$('#clearMoves').onclick=()=>{$('#moveMaterial').value='';$('#moveFrom').value='';$('#moveTo').value='';refresh()};$('#exportMoves').onclick=()=>{const list=refresh();downloadCSV('movimientos-gromex.csv',[['Fecha','Material','Tipo','Cantidad','Unidad','Concepto','Referencia'],...list.map(x=>[x.date,material(x.materialId).name,x.type==='IN'?'Entrada':'Salida',x.qty,material(x.materialId).unit,x.concept,x.reference])])};refresh()}
function movementModal(type='IN',mid=''){openModal(type==='IN'?'Registrar entrada':'Registrar salida',type==='IN'?'Aumentará la existencia disponible.':'Descontará la existencia disponible.',`<div class="form-grid"><div class="field full"><label>MATERIAL</label><select id="mvMaterial">${S.materials.map(m=>`<option value="${m.id}" ${m.id===mid?'selected':''}>${esc(m.name)} · ${num(m.stock)} ${m.unit}</option>`).join('')}</select></div><div class="field"><label>FECHA</label><input type="date" id="mvDate" value="${today()}"></div><div class="field"><label>CANTIDAD</label><input type="number" min=".001" step="any" id="mvQty"></div><div class="field full"><label>CONCEPTO</label><input id="mvConcept" placeholder="Compra, ajuste, consumo de producción…"></div><div class="field full"><label>REFERENCIA</label><input id="mvReference" value="${nextFolio(type==='IN'?'ENT':'SAL',S.movements.map((x,i)=>({folio:x.reference||String(i)})))}"></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveMovement">Guardar movimiento</button>`);$('#saveMovement').onclick=()=>{const m=material($('#mvMaterial').value),qty=+$('#mvQty').value||0;if(qty<=0)return toast('Ingresa una cantidad válida');if(type==='OUT'&&qty>m.stock)return toast(`Existencia insuficiente: ${num(m.stock)} ${m.unit}`);m.stock=Math.round((m.stock+(type==='IN'?qty:-qty))*100000)/100000;S.movements.unshift({id:uid(),date:$('#mvDate').value,materialId:m.id,type,qty,concept:$('#mvConcept').value||'Movimiento de inventario',reference:$('#mvReference').value});log(`${type==='IN'?'Entrada':'Salida'} de ${m.name}`);save();closeModal();toast('Movimiento registrado');render()}}

function renderProduction(){setPage('Producción','PLANTA Y ÓRDENES');const active=S.orders.filter(o=>o.status!=='Terminada'),done=S.orders.filter(o=>o.status==='Terminada');$('#content').innerHTML=sectionHead('Órdenes de producción','Programa fabricación y descuenta automáticamente los materiales al iniciar.','<button class="primary" id="newOrder">＋ Nueva orden</button>')+`<div class="metrics">${stat('◩','EN PROCESO',active.filter(o=>o.status==='En proceso').length,'Producción activa','orange')}${stat('◷','PLANIFICADAS',active.filter(o=>o.status==='Planificada').length,'Pendientes de iniciar','blue')}${stat('✓','TERMINADAS',done.length,'Histórico','teal')}${stat('▦','PIEZAS PRODUCIDAS',num(done.reduce((s,o)=>s+o.qty,0)),'Órdenes terminadas','blue')}</div><div id="orderList">${S.orders.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(o=>{const p=product(o.productId);return `<article class="order"><div><small>${o.folio}${o.quoteId?' · '+esc(S.quotations.find(q=>q.id===o.quoteId)?.folio||''):''}</small><strong style="font-size:13px">${esc(p.name)}</strong></div><div><small>CANTIDAD</small><strong>${num(o.qty)} ${p.unit}</strong></div><div><small>FECHA</small><strong>${dateFmt(o.date)}</strong></div><div><small>AVANCE · ${o.progress}%</small><div class="progress" style="margin-top:6px"><i class="${o.status==='Terminada'?'':'orange'}" style="width:${o.progress}%"></i></div></div><div>${tag(o.status)}${o.status!=='Terminada'?`<button class="btn btn-outline btn-sm" style="margin-left:8px" data-advance-order="${o.id}">${o.status==='Planificada'?'Iniciar':'Terminar'}</button>`:''}</div></article>`}).join('')||empty('◩','Sin órdenes','Crea la primera orden de producción.')}</div>`;$('#newOrder').onclick=orderModal;$$('[data-advance-order]').forEach(b=>b.onclick=()=>advanceOrder(b.dataset.advanceOrder))}
function orderModal(){const approved=S.quotations.filter(q=>q.status==='Aprobada');openModal('Nueva orden de producción','Puede vincularse a una cotización aprobada.',`<div class="form-grid"><div class="field full"><label>COTIZACIÓN DE ORIGEN (OPCIONAL)</label><select id="oQuote"><option value="">Sin cotización</option>${approved.map(q=>`<option value="${q.id}">${q.folio} · ${esc(client(q.clientId).name)}</option>`).join('')}</select></div><div class="field full"><label>PRODUCTO</label><select id="oProduct">${S.products.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>CANTIDAD</label><input type="number" min="1" id="oQty" value="1000"></div><div class="field"><label>FECHA PROGRAMADA</label><input type="date" id="oDate" value="${today()}"></div></div><div class="panel" style="margin-top:15px"><h3 style="font-size:13px">Materiales requeridos</h3><div class="explosion" id="orderReq"></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveOrder">Programar orden</button>`);const req=()=>{const p=product($('#oProduct').value),qty=+$('#oQty').value||0;$('#orderReq').innerHTML=Object.entries(p.recipe||{}).map(([mid,per])=>{const m=material(mid),need=per*qty,ok=m.stock>=need;return `<div><small>${esc(m.name)}</small><strong class="${ok?'':'danger-text'}">${num(need)} ${m.unit}</strong><small>Disponible ${num(m.stock)}</small></div>`}).join('')};$('#oQuote').onchange=()=>{const q=S.quotations.find(x=>x.id===$('#oQuote').value);if(q&&q.items[0]){$('#oProduct').value=q.items[0].productId;$('#oQty').value=q.items[0].qty;req()}};$('#oProduct').onchange=req;$('#oQty').oninput=req;req();$('#saveOrder').onclick=()=>{const qty=+$('#oQty').value||0;if(qty<=0)return toast('Ingresa una cantidad válida');const o={id:uid(),folio:nextFolio('OP',S.orders),quoteId:$('#oQuote').value,productId:$('#oProduct').value,qty,date:$('#oDate').value,status:'Planificada',progress:0,consumed:false};S.orders.unshift(o);log(`Orden ${o.folio} programada`);save();closeModal();toast('Orden programada');render()}}
function advanceOrder(id){const o=S.orders.find(x=>x.id===id),p=product(o.productId);if(o.status==='Planificada'){const requirements=Object.entries(p.recipe||{}).map(([mid,per])=>({m:material(mid),qty:per*o.qty})),missing=requirements.filter(x=>x.m.stock<x.qty);if(missing.length)return toast(`Material insuficiente: ${missing.map(x=>x.m.name).join(', ')}`);requirements.forEach(x=>{x.m.stock=Math.round((x.m.stock-x.qty)*100000)/100000;S.movements.unshift({id:uid(),date:today(),materialId:x.m.id,type:'OUT',qty:x.qty,concept:`Producción ${o.folio}`,reference:nextFolio('SAL',S.movements.map((m,i)=>({folio:m.reference||String(i)})))})});o.status='En proceso';o.progress=50;o.consumed=true;toast('Producción iniciada y materiales descontados')}else{o.status='Terminada';o.progress=100;toast('Orden terminada')}log(`${o.folio} → ${o.status}`);save();render()}

function renderReports(){setPage('Reportes','ANÁLISIS Y EXPORTACIÓN');const from=reportFilters.from,to=reportFilters.to,qs=S.quotations.filter(q=>(!from||q.issue>=from)&&(!to||q.issue<=to)),moves=S.movements.filter(m=>(!from||m.date>=from)&&(!to||m.date<=to)),approved=qs.filter(q=>q.status==='Aprobada'),amount=approved.reduce((s,q)=>s+quoteTotals(q).total,0),conversion=qs.length?approved.length/qs.length*100:0,outs=moves.filter(m=>m.type==='OUT'),byMat={};outs.forEach(x=>byMat[x.materialId]=(byMat[x.materialId]||0)+x.qty);$('#content').innerHTML=sectionHead('Reportes','Indicadores por periodo y exportación para análisis externo.','<button class="secondary" id="csvQuotes">Exportar cotizaciones</button><button class="secondary" id="csvMoves">Exportar movimientos</button>')+`<div class="toolbar"><div class="field"><label>DESDE</label><input type="date" id="rFrom" value="${from}"></div><div class="field"><label>HASTA</label><input type="date" id="rTo" value="${to}"></div><button class="btn btn-blue" id="applyReport">Aplicar periodo</button></div><div class="metrics">${stat('$','VENTAS APROBADAS',money(amount),`${approved.length} cotizaciones`,'teal')}${stat('%','CONVERSIÓN',`${num(conversion)}%`,'Aprobadas / total','blue')}${stat('▤','COTIZACIONES',qs.length,'En el periodo','orange')}${stat('⇄','MOVIMIENTOS',moves.length,'Entradas y salidas','blue')}</div><div class="grid two"><article class="panel"><div class="panel-head"><div><h3>Cotizaciones por estado</h3><p>Distribución del periodo</p></div></div>${['Borrador','Enviada','Pendiente','Aprobada','Rechazada'].map(st=>{const n=qs.filter(q=>q.status===st).length;return `<div class="progress-row"><div class="progress-label"><span>${st}</span><b>${n}</b></div><div class="progress"><i style="width:${qs.length?n/qs.length*100:0}%;background:${st==='Aprobada'?'var(--teal)':st==='Rechazada'?'var(--red)':'var(--blue)'}"></i></div></div>`}).join('')}</article><article class="panel"><div class="panel-head"><div><h3>Consumo por material</h3><p>Salidas del inventario</p></div></div>${Object.entries(byMat).map(([mid,q])=>`<div class="progress-row"><div class="progress-label"><span>${esc(material(mid).name)}</span><b>${num(q)} ${material(mid).unit}</b></div><div class="progress"><i class="orange" style="width:${Math.min(100,q/Math.max(...Object.values(byMat))*100)}%"></i></div></div>`).join('')||'<p class="hint">Sin consumos en el periodo.</p>'}</article></div>`;$('#applyReport').onclick=()=>{reportFilters={from:$('#rFrom').value,to:$('#rTo').value};renderReports()};$('#csvQuotes').onclick=()=>downloadCSV('cotizaciones-gromex.csv',[['Folio','Fecha','Cliente','Estado','Subtotal','IVA','Total','Usuario'],...qs.map(q=>{const t=quoteTotals(q);return[q.folio,q.issue,client(q.clientId).name,q.status,t.subtotal,t.tax,t.total,q.user]})]);$('#csvMoves').onclick=()=>downloadCSV('movimientos-gromex.csv',[['Fecha','Material','Tipo','Cantidad','Unidad','Concepto','Referencia'],...moves.map(x=>[x.date,material(x.materialId).name,x.type,x.qty,material(x.materialId).unit,x.concept,x.reference])])}
function downloadCSV(filename,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Archivo exportado')}

function renderAdmin(){setPage('Administración','USUARIOS Y CONFIGURACIÓN');$('#content').innerHTML=sectionHead('Administración','Empresa, usuarios, actividad y respaldo de información.','<button class="secondary" id="backupBtn">Descargar respaldo</button><button class="primary" id="newUser">＋ Nuevo usuario</button>')+`<div class="grid two"><article class="panel"><div class="panel-head"><div><h3>Datos de la empresa</h3><p>Aparecen en las cotizaciones impresas.</p></div></div><div class="form-grid"><div class="field"><label>NOMBRE COMERCIAL</label><input id="coName" value="${esc(S.company.name)}"></div><div class="field"><label>RAZÓN SOCIAL</label><input id="coLegal" value="${esc(S.company.legal)}"></div><div class="field"><label>RFC</label><input id="coRfc" value="${esc(S.company.rfc)}"></div><div class="field"><label>TELÉFONO</label><input id="coPhone" value="${esc(S.company.phone)}"></div><div class="field"><label>CORREO</label><input id="coEmail" value="${esc(S.company.email)}"></div><div class="field"><label>IVA PREDETERMINADO (%)</label><input type="number" id="coTax" value="${S.company.tax}"></div><div class="field full"><label>DIRECCIÓN</label><input id="coAddress" value="${esc(S.company.address)}"></div></div><button class="primary" id="saveCompany" style="margin-top:14px">Guardar configuración</button></article><article class="panel"><div class="panel-head"><div><h3>Actividad reciente</h3><p>Acciones realizadas en el sistema.</p></div></div>${S.activity.slice(0,8).map(a=>`<div style="padding:9px 0;border-bottom:1px solid var(--line)"><b style="font-size:10px">${esc(a.text)}</b><p class="hint">${dateFmt(a.date)} · ${esc(a.user)}</p></div>`).join('')||'<p class="hint">La actividad aparecerá aquí.</p>'}</article></div><article class="panel" style="margin-top:15px"><div class="panel-head"><div><h3>Usuarios y roles</h3><p>Administrador, Producción y Almacén.</p></div></div><div class="table-wrap"><table><thead><tr><th>USUARIO</th><th>CORREO</th><th>ROL</th><th>ESTADO</th><th></th></tr></thead><tbody>${S.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${tag(u.active?'Activo':'Inactivo')}</td><td><button class="btn btn-outline btn-sm" data-user-edit="${u.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></article>`;$('#newUser').onclick=()=>userModal();$$('[data-user-edit]').forEach(b=>b.onclick=()=>userModal(b.dataset.userEdit));$('#saveCompany').onclick=()=>{Object.assign(S.company,{name:$('#coName').value,legal:$('#coLegal').value,rfc:$('#coRfc').value,phone:$('#coPhone').value,email:$('#coEmail').value,tax:+$('#coTax').value||0,address:$('#coAddress').value});log('Configuración de empresa actualizada');save();toast('Configuración guardada')};$('#backupBtn').onclick=backup}
function userModal(id){const old=id?S.users.find(u=>u.id===id):null,u=old?structuredClone(old):{id:uid(),name:'',email:'',role:'Almacén',active:true};openModal(old?'Editar usuario':'Nuevo usuario','Define su rol de acceso al sistema.',`<div class="form-grid"><div class="field full"><label>NOMBRE</label><input id="uName" value="${esc(u.name)}"></div><div class="field full"><label>CORREO</label><input type="email" id="uEmail" value="${esc(u.email)}"></div><div class="field"><label>ROL</label><select id="uRole">${['Administrador','Producción','Almacén'].map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>ESTADO</label><select id="uActive"><option value="1" ${u.active?'selected':''}>Activo</option><option value="0" ${!u.active?'selected':''}>Inactivo</option></select></div></div>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="saveUser">Guardar usuario</button>`);$('#saveUser').onclick=()=>{u.name=$('#uName').value.trim();if(!u.name)return toast('Escribe el nombre');u.email=$('#uEmail').value;u.role=$('#uRole').value;u.active=$('#uActive').value==='1';if(old)Object.assign(old,u);else S.users.push(u);log(`Usuario ${u.name} guardado`);save();closeModal();toast('Usuario guardado');render()}}
function backup(){const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`respaldo-gromex-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Respaldo descargado')}
function switchUser(){openModal('Cambiar usuario','Simula el acceso con los roles configurados.',`<div class="grid">${S.users.filter(u=>u.active).map(u=>`<button class="secondary" data-switch-user="${u.id}" style="justify-content:flex-start"><span class="avatar">${u.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span style="text-align:left"><b>${esc(u.name)}</b><small style="display:block">${esc(u.role)}</small></span></button>`).join('')}</div>`,`<button class="secondary" data-close>Cancelar</button>`);$$('[data-switch-user]').forEach(b=>b.onclick=()=>{S.sessionId=b.dataset.switchUser;if(!roleAllowed(currentView))currentView='dashboard';save();closeModal();toast(`Sesión: ${user().name}`);render()})}
function bindGo(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bindQuoteActions()}
function globalSearch(e){const q=e.target.value.trim().toLowerCase();$('.search-results')?.remove();if(q.length<2)return;const results=[...S.quotations.filter(x=>(x.folio+client(x.clientId).name).toLowerCase().includes(q)).slice(0,4).map(x=>({title:x.folio,sub:client(x.clientId).name,view:'quote',id:x.id})),...S.clients.filter(x=>(x.name+x.company).toLowerCase().includes(q)).slice(0,3).map(x=>({title:x.name,sub:'Cliente',view:'client',id:x.id})),...S.suppliers.filter(x=>(x.name+x.contact+x.category).toLowerCase().includes(q)).slice(0,3).map(x=>({title:x.name,sub:'Proveedor · '+x.category,view:'supplier',id:x.id})),...S.materials.filter(x=>x.name.toLowerCase().includes(q)).slice(0,3).map(x=>({title:x.name,sub:'Material',view:'inventory'}))];const d=document.createElement('div');d.className='search-results';d.innerHTML=results.map((r,i)=>`<button class="search-result" data-result="${i}"><strong>${esc(r.title)}</strong><small>${esc(r.sub)}</small></button>`).join('')||'<p class="hint" style="padding:10px">Sin resultados</p>';document.body.appendChild(d);$$('[data-result]',d).forEach(b=>b.onclick=()=>{const r=results[+b.dataset.result];d.remove();e.target.value='';if(r.view==='quote')viewQuote(r.id);else if(r.view==='client')clientDetail(r.id);else if(r.view==='supplier')supplierDetail(r.id);else go(r.view)})}

$$('.nav-item').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#newQuoteTop').onclick=()=>openQuoteForm();$('#userCard').onclick=switchUser;$('#globalSearch').oninput=globalSearch;document.addEventListener('click',e=>{if(!e.target.closest('.global-search')&&!e.target.closest('.search-results'))$('.search-results')?.remove()});render();
